1	// Shared black-box harness: spawn `node server.mjs` and talk to it over HTTP or raw TCP.
2	import assert from 'node:assert/strict';
3	import { spawn } from 'node:child_process';
4	import http from 'node:http';
5	import net from 'node:net';
6	import fs from 'node:fs';
7	import os from 'node:os';
8	import path from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	
11	export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
12	export const SERVER = path.join(ROOT, 'server.mjs');
13	export const JSON_TYPE = 'application/json; charset=utf-8';
14	export const JSON_HEADERS = Object.freeze({ 'content-type': 'application/json' });
15	export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
16	const EXIT_TIMEOUT_MS = 5000;
17	
18	/** Fresh temp folder, removed after the test. */
19	export function makeTmp(t) {
20	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'booking-h-'));
21	  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
22	  return dir;
23	}
24	
25	/**
26	 * Spawns the server. `env` entries override the defaults (PORT=0, DATA_FILE=<dir>/data.json);
27	 * an entry whose value is `undefined` removes that variable entirely.
28	 */
29	export function spawnServer(dir, { env = {}, cwd } = {}) {
30	  const merged = { ...process.env, PORT: '0', DATA_FILE: path.join(dir, 'data.json'), ...env };
31	  const fullEnv = Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
32	  return spawn(process.execPath, [SERVER], { env: fullEnv, cwd: cwd ?? dir });
33	}
34	
35	/**
36	 * Starts the server and resolves once it prints the listening line.
37	 * `out()` / `err()` return everything written to stdout / stderr so far.
38	 */
39	export function startServer(t, dir, opts = {}) {
40	  const child = spawnServer(dir, opts);
41	  t.after(() => child.kill('SIGKILL'));
42	  let stdout = '';
43	  let stderr = '';
44	  child.stdout.on('data', (d) => { stdout += d; });
45	  child.stderr.on('data', (d) => { stderr += d; });
46	  return new Promise((resolve, reject) => {
47	    const onData = () => {
48	      const m = LISTEN_RE.exec(stdout);
49	      if (!m) return;
50	      child.stdout.off('data', onData);
51	      child.off('exit', onExit);
52	      resolve({ port: Number(m[1]), child, out: () => stdout, err: () => stderr });
53	    };
54	    const onExit = (code) => reject(new Error(`exited ${code} before listening: ${stderr}`));
55	    child.stdout.on('data', onData);
56	    child.on('exit', onExit);
57	  });
58	}
59	
60	/** Spawns the server in a fresh temp dir; returns { dir, port, child, out, err }. */
61	export async function boot(t, opts = {}) {
62	  const dir = makeTmp(t);
63	  const srv = await startServer(t, dir, opts);
64	  return { dir, ...srv };
65	}
66	
67	/** Runs the server until it exits; resolves { code, stdout, stderr }. Rejects after 5 s. */
68	export function runToExit(t, dir, opts = {}) {
69	  const child = spawnServer(dir, opts);
70	  t.after(() => child.kill('SIGKILL'));
71	  return new Promise((resolve, reject) => {
72	    let stdout = '';
73	    let stderr = '';
74	    const timer = setTimeout(() => reject(new Error('server did not exit in 5s')), EXIT_TIMEOUT_MS);
75	    child.stdout.on('data', (d) => { stdout += d; });
76	    child.stderr.on('data', (d) => { stderr += d; });
77	    child.on('exit', (code) => {
78	      clearTimeout(timer);
79	      resolve({ code, stdout, stderr });
80	    });
81	  });
82	}
83	
84	/** HTTP request; resolves { status, headers, text, json } (json undefined when not JSON). */
85	export function request(port, method, reqPath, { headers = {}, body } = {}) {
86	  return new Promise((resolve, reject) => {
87	    const opts = { host: '127.0.0.1', port, method, path: reqPath, headers, agent: false };
88	    const req = http.request(opts, (res) => {
89	      const chunks = [];
90	      res.on('data', (c) => chunks.push(c));
91	      res.on('end', () => {
92	        const text = Buffer.concat(chunks).toString('utf8');
93	        let json;
94	        try { json = JSON.parse(text); } catch { json = undefined; }
95	        resolve({ status: res.statusCode, headers: res.headers, text, json });
96	      });
97	    });
98	    req.on('error', reject);
99	    req.end(body);
100	  });
101	}
102	
103	/** POST /api/bookings; objects are JSON-encoded, strings and Buffers are sent as is. */
104	export function post(port, obj, headers = JSON_HEADERS) {
105	  const body = typeof obj === 'string' || Buffer.isBuffer(obj) ? obj : JSON.stringify(obj);
106	  return request(port, 'POST', '/api/bookings', { headers, body });
107	}
108	
109	/**
110	 * Sends raw bytes over TCP and resolves the parsed status line, lower-cased headers and body text.
111	 * Use for request lines or headers that node:http would refuse to send.
112	 */
113	export function rawRequest(port, raw) {
114	  return new Promise((resolve, reject) => {
115	    const socket = net.connect(port, '127.0.0.1', () => socket.end(raw));
116	    const chunks = [];
117	    socket.on('data', (c) => chunks.push(c));
118	    socket.on('error', reject);
119	    socket.on('end', () => {
120	      const text = Buffer.concat(chunks).toString('utf8');
121	      const split = text.indexOf('\r\n\r\n');
122	      const head = split === -1 ? text : text.slice(0, split);
123	      const bodyText = split === -1 ? '' : text.slice(split + 4);
124	      const [statusLine, ...headerLines] = head.split('\r\n');
125	      const headers = Object.fromEntries(headerLines.map((l) => {
126	        const i = l.indexOf(':');
127	        return [l.slice(0, i).trim().toLowerCase(), l.slice(i + 1).trim()];
128	      }));
129	      let json;
130	      try { json = JSON.parse(bodyText); } catch { json = undefined; }
131	      resolve({ status: Number(statusLine.split(' ')[1]), headers, text: bodyText, json });
132	    });
133	  });
134	}
135	
136	/** A valid booking body; `over` replaces fields. */
137	export const valid = (over = {}) => ({
138	  room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '10:00', end: '11:00', ...over,
139	});
140	
141	/** Asserts status, exact `{error}` body and the JSON content type. */
142	export function assertError(res, status, message) {
143	  assert.equal(res.status, status);
144	  assert.deepEqual(res.json, { error: message });
145	  assert.equal(res.headers['content-type'], JSON_TYPE);
146	}
147	
148	/** Resolves true when 127.0.0.1:<port> can be bound right now. */
149	export function portIsFree(port) {
150	  return new Promise((resolve) => {
151	    const probe = net.createServer();
152	    probe.once('error', () => resolve(false));
153	    probe.listen(port, '127.0.0.1', () => probe.close(() => resolve(true)));
154	  });
155	}
